template.solver:
def solve(N):
    # Уравнение эквивалентно (a-b)(a+k-b)=b^2. Положим x=a-b, тогда x=d*p^2, x+k=d*q^2, b=d*p*q,
    # откуда k=d*(q-p)*(q+p), a=d*p*(p+q). Обозначим s=p+q, t=q-p, тогда k=d*s*t, a=d*p*s.
    # Минимальный d при фиксированных s,t: наименьшее d с d*p*s > N.
    best = None
    S = int(sqrt(2 * N)) + 5
    for s in range(2, S + 1):
        for t in range(1, s):
            if (s - t) % 2:
                continue
            p = (s - t) // 2
            if p < 1:
                continue
            d = N // (p * s) + 1
            k = d * s * t
            if best is None or k < best:
                best = k
    return best
